'use strict';
const Accounts={tab:'users',query:{},names:{admin:'系统管理员',logistics_manager:'物流经理',site_supervisor:'物流现场主管',logistics_operator:'物流操作员',production_dept:'生产管理部'},
async render(){if(CurrentUser.role_code!=='admin')throw Error('仅系统管理员可以管理账号');const [r,o,p,s]=await Promise.all([API.request('/users?'+new URLSearchParams(this.query)),API.request('/users/options'),API.request('/security/roles'),API.request('/security/policy')]);Object.assign(this,{users:r.items,options:o,roles:p.items,policy:s});Router.page('账户管理',`<p>维护员工账号及五角色权限。删除采用归档方式，业务历史完整保留。</p><div class="account-tabs" role="tablist"><button data-account-tab="users" class="button">账号管理</button><button data-account-tab="roles" class="button">角色与权限</button></div><p id="account-error" class="error" role="alert"></p><div id="account-content"></div>`);document.querySelectorAll('[data-account-tab]').forEach(b=>b.onclick=()=>{this.tab=b.dataset.accountTab;this.draw();});this.draw();},
error(e){$('account-error').textContent=e.message;},state(u){return u.deleted_at?'已删除':u.active?'启用':'停用';},rolesHTML(code){if(code&&!this.roles.some(r=>r.code===code))code='logistics_operator';return this.roles.map(r=>`<option value="${r.code}" ${code===r.code?'selected':''}>${this.names[r.code]}</option>`).join('');},date(v){return v?new Date(v).toISOString().replace('T',' ').slice(0,16):'—';},
draw(){document.querySelectorAll('[data-account-tab]').forEach(b=>{const on=b.dataset.accountTab===this.tab;b.className='button '+(on?'primary':'secondary');b.setAttribute('role','tab');b.setAttribute('aria-selected',on);});this.tab==='users'?this.drawUsers():this.drawRoles();},
drawUsers(){const q=this.query;$('account-content').innerHTML=`<form id="account-filter" class="account-toolbar"><label>搜索账号<input name="q" value="${esc(q.q||'')}" maxlength="80" placeholder="用户名或显示名称"></label><label>所属角色<select name="role"><option value="">全部角色</option>${this.rolesHTML(q.role)}</select></label><label>账号状态<select name="status">${[['','未删除账号'],['active','启用'],['disabled','停用'],['deleted','已删除'],['all','全部账号']].map(([v,n])=>`<option value="${v}" ${q.status===v?'selected':''}>${n}</option>`).join('')}</select></label><button class="button secondary">搜索</button><button type="button" id="account-create" class="button primary">新建账号</button></form><div class="account-table-scroll"><table class="account-table"><caption>员工账号列表 · UTC</caption><thead><tr>${['用户名','所属角色','账号状态','创建时间','最近登录时间','操作'].map(n=>`<th>${n}</th>`).join('')}</tr></thead><tbody>${this.users.map(u=>`<tr><td><strong data-no-i18n>${esc(u.username)}</strong><small data-no-i18n>${esc(u.display_name)}</small></td><td>${this.names[u.role_code]||'历史角色'}</td><td><span class="account-status ${u.deleted_at?'archived':u.active?'active':'disabled'}">${this.state(u)}</span></td><td>${this.date(u.created_at)}</td><td>${this.date(u.last_login_at)}</td><td><details class="account-actions"><summary>操作</summary><div>${(u.deleted_at?[['restore','恢复账号']]:[['edit','编辑账号'],['reset','重置密码'],['toggle',u.active?'停用':'启用'],['delete','删除账号']]).map(([a,n])=>`<button class="button ${a==='delete'?'danger':'secondary'}" data-account-action="${a}" data-id="${u.id}" ${(u.id===CurrentUser.id&&['toggle','delete'].includes(a))||(a==='toggle'&&!this.names[u.role_code])?'disabled':''}>${n}</button>`).join('')}</div></details></td></tr>`).join('')}</tbody></table></div>${!this.users.length?'<p>当前筛选无账号</p>':''}`;$('account-filter').onsubmit=e=>{e.preventDefault();this.query=Object.fromEntries(new FormData(e.target));this.render().catch(e=>this.error(e));};$('account-create').onclick=()=>this.edit();document.querySelectorAll('[data-account-action]').forEach(b=>b.onclick=()=>this.action(b.dataset.accountAction,this.users.find(u=>u.id===b.dataset.id)).catch(e=>this.error(e)));},
async action(a,u){if(a==='edit')return this.edit(u);if(['reset','restore'].includes(a))return this.password(u,a);if(a==='delete')return this.remove(u);await API.request('/users/'+u.id,{method:'PATCH',body:{active:!u.active}});await this.render();},
async submit(e,path,method,body,u){e.preventDefault();e.submitter.disabled=true;try{await API.request(path,{method,body});e.target.reset();if(u?.id===CurrentUser.id){location.reload();return;}await this.render();notify('账号已保存');}catch(err){$('account-form-error').textContent=err.message;e.submitter.disabled=false;}},
edit(u){dialog(u?'编辑账号':'新建账号',`<form id="account-edit" class="account-form"><label>用户名<input name="username" value="${esc(u?.username||'')}" ${u?'readonly':''} required pattern="[a-z][a-z0-9_]{2,39}" maxlength="40" data-no-i18n></label><label>显示名称<input name="display_name" value="${esc(u?.display_name||'')}" required maxlength="80" data-no-i18n></label><label>所属角色<select name="role_code">${this.rolesHTML(u?.role_code||'logistics_operator')}</select></label><label>账号状态<select name="active"><option value="true" ${u?.active!==false?'selected':''}>启用</option><option value="false" ${u?.active===false?'selected':''}>停用</option></select></label>${!u?'<label>初始密码<input type="password" name="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><fieldset><legend>授权项目范围</legend>'+this.options.projects.map(p=>`<label class="check-row"><input type="checkbox" name="project" value="${p.id}" checked><span data-no-i18n>${esc(p.name)}</span></label>`).join('')+'</fieldset>':'<p>现有数据范围保持不变。角色变更将撤销该账号旧会话。</p>'}<p id="account-form-error" class="error" role="alert"></p><div class="account-form-actions"><button class="button primary">保存</button><button type="button" class="button secondary" id="account-cancel">取消</button></div></form>`);$('account-cancel').onclick=()=>$('dialog').close();$('account-edit').onsubmit=e=>{const d=new FormData(e.target),body={display_name:d.get('display_name'),role_code:d.get('role_code'),active:d.get('active')==='true'};if(!u)Object.assign(body,{username:d.get('username'),password:d.get('password'),scopes:d.getAll('project').map(project_id=>({project_id}))});this.submit(e,'/users'+(u?'/'+u.id:''),u?'PATCH':'POST',body,u);};},
password(u,a){dialog(a==='restore'?'恢复账号':'重置密码',`<p data-no-i18n>${esc(u.username)}</p><p>设置新密码后旧会话立即失效，请安全交付密码。</p><form id="account-password" class="account-form">${a==='restore'?`<label>所属角色<select name="role_code">${this.rolesHTML(u.deleted_role_code||u.role_code)}</select></label>`:''}<label>新密码（12—128字符）<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><p id="account-form-error" class="error" role="alert"></p><button class="button primary">保存新密码</button></form>`);$('account-password').onsubmit=e=>this.submit(e,'/users/'+u.id+(a==='restore'?'/restore':'/reset-password'),'POST',Object.fromEntries(new FormData(e.target)),u);},
async remove(u){const c=await API.request('/users/'+u.id+'/deletion-check'),tasks=Object.values(c.pending).some(n=>n>0);dialog('删除账号',`<p>删除后无法登录，历史业务和审批记录完整保留。</p><dl><dt>用户名</dt><dd data-no-i18n>${esc(u.username)}</dd><dt>所属角色</dt><dd data-i18n>${this.names[u.role_code]||'历史角色'}</dd><dt>账号状态</dt><dd>${this.state(u)}</dd></dl><form id="account-delete" class="account-form"><label>再次输入用户名<input name="username" required autocomplete="off" data-no-i18n></label><label>删除原因<textarea name="reason" required maxlength="1000" data-no-i18n></textarea></label>${tasks?`<p class="dialog-notice">关联待办：入库单 ${c.pending.receipts}；Lot ${c.pending.lots}；装车单 ${c.pending.loads}</p><label class="check-row"><input name="acknowledge_pending" type="checkbox" required>已核查待办，理解不会转移审批历史</label>`:''}<p id="account-form-error" class="error" role="alert"></p><button class="button danger">确认删除账号</button></form>`);$('account-delete').onsubmit=e=>{const d=new FormData(e.target);this.submit(e,'/users/'+u.id,'DELETE',{username:d.get('username'),reason:d.get('reason'),acknowledge_pending:d.has('acknowledge_pending')});};},
groups:{dashboard:'信息总览',inventory:'库存查询与库存地图',label:'库存查询与库存地图',master:'客户管理',customer:'客户管理',plan:'备货管理',receipt:'入库管理',allocation:'备货管理',sample:'备货管理',weigh:'备货管理',lot:'备货管理',load:'出库管理',outbound:'出库管理',users:'账户管理',roles:'账户管理',system:'账户管理',audit:'账户管理'},
subjects:{dashboard:'信息总览',inventory:'库存查询',label:'标签',master:'基础资料',customer:'客户',plan:'销售计划',receipt:'入库单',allocation:'备货',sample:'取样',weigh:'检斤',lot:'Lot',load:'装车',outbound:'出库',users:'账号',roles:'角色',system:'系统设置',audit:'操作日志',report:'报表',stocktake:'盘点',exception:'异常',adjust:'库存调整',move:'移库'},permissionLabels:{'inventory:read':'库存与地图查看','allocation:write':'备货创建、取样、检斤、铅封及提交','allocation:review':'备货审核及授权更正','receipt:write':'入库创建、编辑及提交','receipt:review':'入库审核','load:write':'装车创建、编辑及确认离场','load:review':'装车审核','users:manage':'员工账号及密码管理','roles:manage':'角色权限配置','system:manage':'测试期自审设置'},ops:{read:'查看',write:'创建及编辑',review:'业务审核',export:'导出',print:'打印标签',manage:'管理',approve:'正式审批',release:'释放锁定','cancel-approve':'取消审批',configure:'配置',depart:'确认离场',gate:'门岗核验',packing:'装箱确认',commerce:'商务复核',supervise:'监督复核'},
drawRoles(){ $('account-content').innerHTML=`<div class="account-role-layout"><aside class="account-role-picker"><h2>选择角色</h2>${this.roles.map(r=>`<button class="button secondary" data-role="${r.code}">${this.names[r.code]}</button>`).join('')}</aside><div><form id="account-role-form"><h2 id="account-role-title"></h2><p id="account-role-summary"></p><p>权限变化影响该角色全部账号，并撤销旧会话。不可突破角色授权上限。</p><div id="account-permissions" class="account-permission-grid"></div><p id="role-dirty" aria-live="polite"></p><div class="account-form-actions"><button class="button primary" id="role-save">保存权限</button><button type="button" class="button secondary" id="role-reset">恢复未保存修改</button></div></form><details class="account-policy"><summary>测试期入库自审</summary><p>仅TEST环境及原生产管理部账号允许入库自审，其他审批仍要求独立审核。</p><label><input id="production-self-review" type="checkbox" ${this.policy.production_receipt_self_review?'checked':''} ${AppConfig.environment!=='test'?'disabled':''}>启用生产管理部测试入库自审</label><button class="button secondary" id="save-auth-policy">保存配置</button></details></div></div>`;let code='admin',dirty=false;
 const draw=()=>{const r=this.roles.find(r=>r.code===code),all=this.roles.find(r=>r.code==='admin').caps,groups={};for(const p of all)(groups[this.groups[p.split(':')[0]]||'其他授权业务']||=[]).push(p);$('account-role-title').textContent=this.names[code];$('account-role-summary').textContent='已授权权限项：'+r.permissions.length+' / '+r.caps.length;const row=p=>`<label class="check-row ${!r.caps.includes(p)?'not-configurable':''}"><input type="checkbox" name="permission" value="${p}" ${r.permissions.includes(p)?'checked':''} ${code==='admin'||!r.caps.includes(p)?'disabled':''}><span>${this.permissionLabels[p]||((this.subjects[p.split(':')[0]]||p.split(':')[0])+' · '+(this.ops[p.split(':')[1]]||p.split(':')[1]))}</span></label>`;$('account-permissions').innerHTML=Object.entries(groups).sort((a,b)=>['信息总览','库存查询与库存地图','客户管理','入库管理','备货管理','出库管理','账户管理','其他授权业务'].indexOf(a[0])-['信息总览','库存查询与库存地图','客户管理','入库管理','备货管理','出库管理','账户管理','其他授权业务'].indexOf(b[0])).map(([g,ps])=>{const allowed=ps.filter(p=>r.caps.includes(p)),denied=ps.filter(p=>!r.caps.includes(p));return `<fieldset><legend>${g}</legend>${allowed.map(row).join('')}${denied.length?'<details class="account-denied"><summary>不可配置权限 · '+denied.length+'</summary>'+denied.map(row).join('')+'</details>':''}</fieldset>`;}).join('');$('role-save').disabled=code==='admin';$('role-dirty').textContent=code==='admin'?'管理员核心权限受保护':'';dirty=false;document.querySelectorAll('[data-role]').forEach(b=>b.classList.toggle('selected',b.dataset.role===code));};
 document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{if(dirty){$('role-dirty').textContent='请先保存或恢复未保存修改';return;}code=b.dataset.role;draw();});$('account-role-form').onchange=()=>{dirty=true;$('role-dirty').textContent='有未保存的权限修改';};$('role-reset').onclick=draw;draw();$('account-role-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const permissions=[...document.querySelectorAll('#account-permissions input:checked')].map(x=>x.value);await API.request('/security/roles/'+code,{method:'PUT',body:{permissions}});this.roles.find(r=>r.code===code).permissions=permissions;draw();notify('权限已更新，相关会话已撤销。');}catch(err){this.error(err);e.submitter.disabled=false;}};$('save-auth-policy').onclick=async()=>{try{const enabled=$('production-self-review').checked;await API.request('/security/policy',{method:'PATCH',body:{production_receipt_self_review:enabled}});AppConfig.productionReceiptSelfReviewEnabled=enabled;this.policy.production_receipt_self_review=enabled;notify('配置已保存并记录审计。');}catch(e){this.error(e);}};
}};
async function manageUsers(){return Router.current==='/workbench/accounts'?Accounts.render():Router.go('/workbench/accounts');}
